INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('on the whole', '整體而言', 'considering everything; generally', '[{"en":"On the whole, the project was a success.","zh-TW":"整體而言，這個專案是成功的。"},{"en":"On the whole, employees are satisfied with the changes.","zh-TW":"整體而言，員工對變動感到滿意。"},{"note":"同義詞：overall, generally, all things considered。"}]', 'expression'),
('to a great extent', '在很大程度上', 'to a large degree', '[{"en":"Success depends to a great extent on teamwork.","zh-TW":"成功在很大程度上取決於團隊合作。"},{"en":"To a certain extent, I agree with you.","zh-TW":"在某種程度上，我同意你的看法。"},{"note":"程度可替換：great, large, certain, some。"}]', 'expression'),
('go out of one''s way', '特意；不辭辛苦', 'to make a special effort beyond what is expected', '[{"en":"She went out of her way to help the new employee.","zh-TW":"她特意幫助新員工。"},{"en":"The staff went out of their way to accommodate our requests.","zh-TW":"工作人員特意配合我們的要求。"},{"note":"表示超越本分的努力。"}]', 'business idiom'),
('from time to time', '偶爾；不時', 'occasionally; sometimes', '[{"en":"We review our policies from time to time.","zh-TW":"我們不時審查我們的政策。"},{"en":"Issues arise from time to time.","zh-TW":"問題偶爾會出現。"},{"note":"同義詞：occasionally, now and then, once in a while。"}]', 'expression'),
('bring back', '恢復；帶回', 'to restore or return something', '[{"en":"The promotion helped bring back lapsed customers.","zh-TW":"促销幫助將休眠客戶招回。"},{"en":"We brought back the popular product due to demand.","zh-TW":"由於需求我們從新推出了這個受歡迎的產品。"}]', 'phrasal verb'),
('miss out on', '錯過；失去機會', 'to fail to take advantage of something', '[{"en":"Do not miss out on this limited-time offer.","zh-TW":"不要錯過這個限時優惠。"},{"en":"She missed out on a great investment opportunity.","zh-TW":"她錯過了一個很好的投資機會。"}]', 'phrasal verb'),
('talk into', '勸說；說服…做某事', 'to persuade someone to do something', '[{"en":"The sales rep talked the client into upgrading the plan.","zh-TW":"業務代表說服客戶升級了方案。"},{"en":"She talked him into signing the contract early.","zh-TW":"她說服他提前簽署了合約。"}]', 'phrasal verb'),
('talk out of', '勸阻；說服不要做', 'to persuade someone not to do something', '[{"en":"She talked him out of making a hasty decision.","zh-TW":"她勸阻了他草率做出決定。"},{"en":"The advisor talked the investor out of a risky move.","zh-TW":"顧問勸阻投資者不要走高風險步驟。"}]', 'phrasal verb'),
('follow suit', '跟進；級繼随之', 'to follow the example of someone else', '[{"en":"After the market leader raised prices competitors followed suit.","zh-TW":"市場領導者提價後，競爭者也級繼跟進。"},{"en":"Other regions followed suit in adopting the new policy.","zh-TW":"其他地區也級繼採用了這項新政策。"}]', 'phrasal verb'),
('give away', '赈送；直接送出', 'to give for free or unintentionally reveal', '[{"en":"We give away free samples at trade shows.","zh-TW":"我們在展覽會發散免費樣品。"},{"en":"She gave away the surprise announcement by mistake.","zh-TW":"她不小心泄露了驚喜公告。"}]', 'phrasal verb'),
('trade in', '以舊換新；易貨', 'to exchange old for new or conduct trade', '[{"en":"Customers can trade in their old device for a discount.","zh-TW":"客戶可用舊機换取折扣。"},{"en":"He traded in his old laptop for the latest model.","zh-TW":"他將舊筆電易換為最新機型。"}]', 'phrasal verb'),
('hook up', '連接；安排指引', 'to connect or arrange access', '[{"en":"Let me hook you up with our product specialist.","zh-TW":"讓我為您安排我們的產品專家。"},{"en":"The technician hooked up the new equipment.","zh-TW":"技術人員連接安裝了新設備。"}]', 'phrasal verb'),
('push for', '主張；推動通過', 'to advocate strongly for something', '[{"en":"She pushed for faster approval of the proposal.","zh-TW":"她主張儘快批准該提案。"},{"en":"Management is pushing for higher productivity targets.","zh-TW":"管理層正在主張提高產能目標。"}]', 'phrasal verb'),
('win over', '爐服；諦導支持', 'to persuade or gain support from someone', '[{"en":"The presentation won over even the most skeptical investors.","zh-TW":"簡報諦服了甚至最多疑的投資者。"},{"en":"She won over the client with her detailed proposal.","zh-TW":"她用詳細的提案爐服了客戶。"}]', 'phrasal verb'),
('back off', '退讓；放棄创署', 'to withdraw or reduce pressure', '[{"en":"They backed off from their initial demands in the negotiation.","zh-TW":"在談判中他們退讓了最初的要求。"},{"en":"The supplier backed off when we threatened to switch.","zh-TW":"當我們表示要更換供應商時對方退讓了。"}]', 'phrasal verb'),
('trade up', '升級購買；買更好的', 'to buy a more expensive or better version of something', '[{"en":"Many customers trade up to the premium plan after trial.","zh-TW":"許多客戶在試用後升級至高階方案。"},{"en":"They traded up to a larger office as the team grew.","zh-TW":"隨著團隊成長他們升級到更大的辦公室。"}]', 'phrasal verb'),
('price out', '將…陀出市場；定價過高', 'to force out of the market by high prices', '[{"en":"High costs are pricing our product out of the mass market.","zh-TW":"高成本正將我們的產品陀出大眾市場。"},{"en":"The retailer priced out small buyers with minimum orders.","zh-TW":"零售商用最小訂單量陀駈了小型買家。"}]', 'phrasal verb'),
('hunt down', '搜尋；追蹤到底', 'to search for and find with great effort', '[{"en":"She hunted down the contact information we needed.","zh-TW":"她搜尋到了我們需要的聯絡資訊。"},{"en":"The analyst hunted down the missing data from archives.","zh-TW":"分析師從檔案中搜尋到了遺失的資料。"}]', 'phrasal verb'),
('deal in', '經營；從事交易', 'to trade in a particular type of goods', '[{"en":"They deal in high-end electronics and accessories.","zh-TW":"他們經營高檔電子產品及配件。"},{"en":"The broker deals in foreign exchange.","zh-TW":"這位中介從事外匯交易。"}]', 'phrasal verb'),
('talk through', '詳細討論；引導討論', 'to discuss in detail or guide through a process', '[{"en":"Let me talk you through the proposal step by step.","zh-TW":"讓我引導你一步一步討論該提案。"},{"en":"They talked through all possible scenarios before deciding.","zh-TW":"他們在決定前詳細討論了所有可能的情境。"}]', 'phrasal verb'),
('fend off', '擋尚；抵御', 'to defend against or ward off', '[{"en":"The company fended off a hostile takeover bid.","zh-TW":"公司抵御了一等恶意收購要符。"},{"en":"They fended off cheaper competitors by focusing on quality.","zh-TW":"他們通過專注品質來擋尚偶价競爭者。"}]', 'phrasal verb'),
('set apart', '使脱穎而出；區別', 'to make noticeably different from others', '[{"en":"Strong customer service sets our brand apart.","zh-TW":"出色的客戶服務讓我們的品牌脱穎而出。"},{"en":"What sets you apart from other candidates?","zh-TW":"是什麼讓你千利其中？"}]', 'phrasal verb'),
('a win-win situation', '雙贏局面；兩方都有利', 'a situation where all parties benefit', '[{"en":"The partnership is a win-win for both companies.","zh-TW":"這次合夸對兩家公司來說是雙贏局面。"},{"en":"This deal is structured as a win-win situation.","zh-TW":"這次交易被設計為雙贏局面。"}]', 'expression'),
('as a last resort', '万不得已的為下；最後手段', 'used only when all other options have failed', '[{"en":"As a last resort we will take the matter to court.","zh-TW":"万不得已的為下我們將提諏訟諸。"},{"en":"Layoffs are a last resort when other cost cuts fail.","zh-TW":"在其他成本削減失敗後，裁員是最後手段。"}]', 'expression'),
('drive a hard bargain', '挑刺的屣价者；難以奉承', 'to negotiate firmly and aggressively to get the best deal', '[{"en":"She drives a hard bargain but always seals the deal.","zh-TW":"她談判阻力很對不過這也讓她周山門就範。"},{"en":"The client drives a hard bargain every contract renewal.","zh-TW":"客戶每次合約續約都挑刺尺度議價。"}]', 'expression'),
('in the works', '在計劃中；尚在為處理中', 'being planned or prepared', '[{"en":"We have a major update in the works for Q4.","zh-TW":"我們為第四季在專層評辭一個重大更新。"},{"en":"There are several new hires in the works.","zh-TW":"目前有幾筆新招聘正在進行中。"}]', 'expression'),
('give someone the benefit of the doubt', '姓呪不知；實雙贏無疑；先信任對方', 'to trust someone even when unsure', '[{"en":"Let us give him the benefit of the doubt on this issue.","zh-TW":"在這個問題上讓我們先信任他。"},{"en":"We gave the vendor the benefit of the doubt on delivery.","zh-TW":"在交貨問題上我們先信任供應商。"}]', 'expression'),
('get down to business', '開始討論正题；隱入正願', 'to start dealing with the main matter at hand', '[{"en":"Let us get down to business and discuss the proposal.","zh-TW":"讓我們開始討論正题，審視該提案。"},{"en":"After the pleasantries they got down to business quickly.","zh-TW":"客套話說完後他們就隱入正题了。"}]', 'expression'),
('par for the course', '與預期相符；理所當然', 'what is normal or expected in a given situation', '[{"en":"Tight deadlines are par for the course in consulting.","zh-TW":"在訮詢業中緊迫的截止日期是常態。"},{"en":"A few bugs at launch are par for the course.","zh-TW":"上市時第一點程序小題是常態。"}]', 'expression'),
('get the most out of', '充分利用；最大化效益', 'to maximize benefit from something', '[{"en":"How do we get the most out of our existing talent?","zh-TW":"我們如何充分利用現有人才？"},{"en":"She gets the most out of her team through clear communication.","zh-TW":"她透過清晰溝通与團隊最大化產效。"}]', 'expression'),
('in due course', '屆時；屆後在適當時機', 'at the appropriate time in the future', '[{"en":"All applications will be reviewed in due course.","zh-TW":"所有申請將屆後審評。"},{"en":"The refund will be processed in due course.","zh-TW":"退款將會在適當時機處理。"}]', 'expression'),
('pour cold water on', '潑湿气气；打击熱情', 'to discourage or criticize an idea', '[{"en":"Do not pour cold water on their enthusiasm.","zh-TW":"不要潑湿他們的熱情。"},{"en":"She poured cold water on the expansion plan.","zh-TW":"她潑湿了擴展計劃的熱情。"}]', 'business idiom'),
('learn the ropes', '學習基本診討；入門', 'to learn the basics of a job or task', '[{"en":"It took him three months to learn the ropes.","zh-TW":"他花了三個月學會了基本工作診討。"},{"en":"She learned the ropes quickly and was promoted within a year.","zh-TW":"她很快就學會了診討，一年內就被升職了。"}]', 'business idiom'),
('know the ropes', '知道診討；經驗豐富', 'to be familiar with how a job or system works', '[{"en":"He knows the ropes of government contracting.","zh-TW":"他熟悉政府合同的診討。"},{"en":"We need someone who already knows the ropes.","zh-TW":"我們需要一個已熟知診討的人。"}]', 'business idiom'),
('change of pace', '改變節奏；變化', 'a shift in activity to break the routine', '[{"en":"The offsite retreat was a welcome change of pace.","zh-TW":"外勤逓修是一個受歡迎的變化。"},{"en":"Working on a new project was a change of pace.","zh-TW":"處理新專案是一種節奏變化。"}]', 'business idiom'),
('a sticking point', '紾級不決的點；難點', 'an issue that prevents progress in negotiations', '[{"en":"Pricing remains a sticking point in the deal.","zh-TW":"定價仍是這次交易中紾級不決的點。"},{"en":"The warranty terms were a sticking point.","zh-TW":"保證條款是連點。"}]', 'business idiom'),
('run a tight ship', '紀律嚴明；紀律嚴格', 'to manage an organization with strict discipline', '[{"en":"She runs a tight ship and all deadlines are met.","zh-TW":"她管理嚴格，所有截止日期一律遵守。"},{"en":"The finance department runs a tight ship with expenses.","zh-TW":"財務部門對支出管控嚴格。"}]', 'business idiom'),
('a tough nut to crack', '難以對付的人事物；難题', 'a difficult problem or person to deal with', '[{"en":"This client is a tough nut to crack in sales.","zh-TW":"這個客戶在銷售上很難對付。"},{"en":"The regulatory environment is a tough nut to crack.","zh-TW":"监管環境很難應對。"}]', 'business idiom'),
('in the driving seat', '握控主動權；居主導地位', 'in control and making key decisions', '[{"en":"After the restructuring she is firmly in the driving seat.","zh-TW":"重組後她穩穩捺揧大局。"},{"en":"We put our clients in the driving seat of their campaign.","zh-TW":"我們讓客戶主導自己的行銷活動。"}]', 'business idiom'),
('get a handle on', '摸清狀況；控制', 'to understand or take control of a situation', '[{"en":"We need to get a handle on the cost overruns.","zh-TW":"我們需要摸清成本超支的情況。"},{"en":"She got a handle on the project risks in her first week.","zh-TW":"她在第一週就摸清了專案風險。"}]', 'business idiom'),
('leave no stone unturned', '穵沒遙漏；尤陥不漏', 'to do everything possible to achieve a result', '[{"en":"We left no stone unturned in the due diligence process.","zh-TW":"我們在尥審過程中穵沒遙漏。"},{"en":"She left no stone unturned in her search for investors.","zh-TW":"她在尋找投資者時穵沒遙漏。"}]', 'business idiom'),
('take stock', '評估情況；盤點', 'to review and assess a situation', '[{"en":"After a year let us take stock of our achievements.","zh-TW":"一年後讓我們盤點我們的成就。"},{"en":"She took stock of her career and decided to change direction.","zh-TW":"她評估自己的職業後決定改變方向。"}]', 'phrasal verb'),
('drum up', '拼命裕招；機助', 'to generate or seek out actively', '[{"en":"We need to drum up more interest in the product.","zh-TW":"我們需要裕招更多人對這個產品的興趣。"},{"en":"She drummed up support for the initiative across departments.","zh-TW":"她在各部門裕招對該計劃的支持。"}]', 'phrasal verb'),
('come through', '成功完成；通過審核', 'to succeed or survive a difficulty', '[{"en":"She always comes through when the team needs her.","zh-TW":"團隊需要時她總是成功層現。"},{"en":"The proposal finally came through after three revisions.","zh-TW":"提案在三次修改後終於通過了。"}]', 'phrasal verb'),
('pin down', '確定；沂定準確細節', 'to fix or determine something precisely', '[{"en":"Can we pin down the exact delivery date?","zh-TW":"我們能確定準確的交貨日期嗎？"},{"en":"She pinned down the cause of the technical issue.","zh-TW":"她查出了技術問題的根本原因。"}]', 'phrasal verb'),
('check in on', '小查一下；確認進度', 'to check how someone is doing or progress of a task', '[{"en":"I will check in on the team mid-week.","zh-TW":"我會對團隊進行期中的進度檢查。"},{"en":"The manager checks in on all projects daily.","zh-TW":"經理每天檢查所有專案的進度。"}]', 'phrasal verb'),
('pile up', '堆積；越益增多', 'to accumulate in large amounts', '[{"en":"Work piled up while she was on leave.","zh-TW":"她請假期間工作不斷堆積。"},{"en":"Do not let tasks pile up - deal with them daily.","zh-TW":"不要讓任務堆積，每天處理。"}]', 'phrasal verb'),
('cover for', '代替；遡圖香噴', 'to substitute for someone or provide an alibi', '[{"en":"Can you cover for me while I am at the hospital?","zh-TW":"我在醒院期間你能代替我嗎？"},{"en":"She covered for the manager during his business trip.","zh-TW":"經理出差期間她代理職務。"}]', 'phrasal verb'),
('step in', '介入；緊急代理', 'to intervene or take over in a crisis', '[{"en":"Management stepped in to resolve the conflict.","zh-TW":"管理層介入解決了衝突。"},{"en":"She stepped in when the project fell behind schedule.","zh-TW":"專案進度落後時她緊急介入。"}]', 'phrasal verb'),
('on the same wavelength', '想法相同；志趣相投', 'thinking or feeling the same way', '[{"en":"We are on the same wavelength regarding the project goals.","zh-TW":"關於專案目標我們想法一致。"},{"en":"Finding a partner on the same wavelength is important.","zh-TW":"找到志趣相投的合作帥很重要。"}]', 'expression');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('face the music', '接受懲罰；勇於承擔後果', 'to accept the consequences of actions', '[{"en":"He made errors and now must face the music.","zh-TW":"他犯了错誤現在必須接受懲罰。"},{"en":"It is time to face the music and apologize to the client.","zh-TW":"該勇於承擔并向客戶道歉了。"}]', 'expression'),
('off the record', '非正式地；不對外公开', 'not intended for official recording or publication', '[{"en":"Off the record she admitted the plan had flaws.","zh-TW":"非正式地她承認該計劃有缺陷。"},{"en":"Can you tell me off the record what happened?","zh-TW":"你能非正式地告訴我發生了什麼嗎？"}]', 'expression'),
('clear the air', '消除誤會；化解緊張', 'to resolve misunderstanding or tension', '[{"en":"We scheduled a meeting to clear the air.","zh-TW":"我們安排了一次會議來化解緊張。"},{"en":"Clearing the air helped them work together more effectively.","zh-TW":"化解誤會讓他們合作更順畅。"}]', 'expression'),
('in the pipeline', '將要推出；進行中', 'being developed or planned for release', '[{"en":"Several new products are in the pipeline for next year.","zh-TW":"明年有幾個新產品將要推出。"},{"en":"We have a new partnership in the pipeline.","zh-TW":"我們有一個新合作安排正在進行中。"}]', 'expression'),
('at the eleventh hour', '在最後一刻；山窮水盡時', 'at the last possible moment', '[{"en":"The deal was saved at the eleventh hour.","zh-TW":"在最後一刻協議得以保全。"},{"en":"They submitted the proposal at the eleventh hour.","zh-TW":"他們在最後期限前送出了提案。"}]', 'expression'),
('bite off more than one can chew', '貪多嘴小；承擔太多', 'to take on more responsibility than one can handle', '[{"en":"Do not bite off more than you can chew with these new clients.","zh-TW":"不要承擔超過自己能力的工作量。"},{"en":"She bit off more than she could chew by taking three projects at once.","zh-TW":"她同時承擔三個專案，已超贏。"}]', 'expression'),
('hit the nail on the head', '說對了；掉展對了', 'to describe something exactly right', '[{"en":"Your analysis hit the nail on the head.","zh-TW":"你的分析完全說中了問題核心。"},{"en":"She hit the nail on the head when she identified the bottleneck.","zh-TW":"她指出甉頼點，完全說對了。"}]', 'expression'),
('keep one''s options open', '保留選擇余地；不輕易下決定', 'to avoid committing to one choice', '[{"en":"She is keeping her options open before accepting the offer.","zh-TW":"她在接受還擞z之前保留選擇余地。"},{"en":"It is wise to keep your options open early in a career.","zh-TW":"職涯早期保留選擇余地是明智的。"}]', 'expression'),
('behind closed doors', '秘密進行；不公開', 'in private, without others present', '[{"en":"The negotiation was conducted behind closed doors.","zh-TW":"謈判在閃門後秘密進行。"},{"en":"Many major decisions are made behind closed doors.","zh-TW":"許多重大決策都是秘密制定的。"}]', 'expression'),
('up in the air', '尚未確定；淅空', 'uncertain or not yet decided', '[{"en":"The merger is still up in the air.","zh-TW":"併購案尚未定案。"},{"en":"Our expansion plans are up in the air pending funding.","zh-TW":"我們的擴展計劃尚需資金確定。"}]', 'expression'),
('ahead of the curve', '走在潮流前利；先進', 'more advanced or innovative than others', '[{"en":"Their R&D department keeps them ahead of the curve.","zh-TW":"他們的研發部門讓公司保持先進地位。"},{"en":"To stay ahead of the curve we must innovate constantly.","zh-TW":"要保持屎尖地位我們必須持續創新。"}]', 'expression'),
('raise the bar', '提高標準；設立更高目標', 'to set a higher standard or expectation', '[{"en":"This product launch really raised the bar for the industry.","zh-TW":"這次產品發展提高了整個行業標準。"},{"en":"We need to raise the bar on customer service.","zh-TW":"我們需要提高客戶服務的標準。"}]', 'expression'),
('get up to speed', '追上進度；蚫清情況', 'to become fully informed or as efficient as others', '[{"en":"Please get up to speed on the new system before Monday.","zh-TW":"請在星期一前熌清新系統的使用。"},{"en":"She spent the first week getting up to speed with her new role.","zh-TW":"她花了第一週熌清新職務的內容。"}]', 'expression'),
('read between the lines', '的弦外之音；理解言外之意', 'to understand the hidden meaning', '[{"en":"Reading between the lines the board is worried about costs.","zh-TW":"從弦外之音可得事源魁鮚成本。"},{"en":"You need to read between the lines to understand his feedback.","zh-TW":"你需要理解弦外之意才能領會他的意見。"}]', 'expression'),
('bite the bullet', '和袈作氣；和袈承受', 'to endure a painful or difficult situation', '[{"en":"We had to bite the bullet and announce the layoffs.","zh-TW":"我們不得不和袈宣布裁員消息。"},{"en":"She bit the bullet and requested a salary review.","zh-TW":"她和袈作氣提出了薪資審查申請。"}]', 'expression'),
('in accordance with', '按照；符合', 'following or complying with a rule or agreement', '[{"en":"The project was completed in accordance with the contract.","zh-TW":"專案按照合同完成。"},{"en":"In accordance with company policy all data must be encrypted.","zh-TW":"按照公司政策所有數據必須加密。"}]', 'prepositional phrase'),
('as a result of', '由於；因為…的結果', 'because of or following something', '[{"en":"As a result of the merger staff numbers increased.","zh-TW":"由於並購，員工人數增加。"},{"en":"As a result of poor planning the launch was delayed.","zh-TW":"由於規劃不居，發布會延遲。"}]', 'prepositional phrase'),
('for the sake of', '為了；看在…的分上', 'for the benefit or purpose of', '[{"en":"For the sake of clarity please use bullet points.","zh-TW":"為了清晰起見，請使用條列項目。"},{"en":"We accepted the compromise for the sake of the partnership.","zh-TW":"為了尊重合作關係我們接受了妙協。"}]', 'prepositional phrase'),
('at the expense of', '以…為代價；犧牲…', 'while causing harm or loss to something else', '[{"en":"Speed should not come at the expense of quality.","zh-TW":"速度不應以犧牲品質為代價。"},{"en":"They cut costs at the expense of customer satisfaction.","zh-TW":"他們以犧牲客戶滿意度為代價削減成本。"}]', 'prepositional phrase'),
('in the absence of', '在缺乏…的情況下；在…不在時', 'when something or someone is not present', '[{"en":"In the absence of clear guidelines staff were confused.","zh-TW":"在缺乏明確指引的情況下員工感到困惑。"},{"en":"In the absence of the manager her deputy took over.","zh-TW":"在經理不在時由其副手接管。"}]', 'prepositional phrase'),
('by virtue of', '憑藉；由於', 'because of or by means of a quality or authority', '[{"en":"She was promoted by virtue of her exceptional performance.","zh-TW":"她憑藉出色的表現獲得晉升。"},{"en":"By virtue of his seniority he chaired the meeting.","zh-TW":"憑藉資歷他主持了會議。"}]', 'prepositional phrase'),
('on the basis of', '基於；以…為依據', 'using something as the reason or foundation', '[{"en":"Promotions are given on the basis of performance.","zh-TW":"晉升是基於表現給予的。"},{"en":"On the basis of research we updated our strategy.","zh-TW":"基於研究我們更新了策略。"}]', 'prepositional phrase'),
('in favor of', '贊成；支持', 'in support of or preferring something', '[{"en":"The board voted in favor of the acquisition.","zh-TW":"董事會投票贊成收購。"},{"en":"She was in favor of a flexible work policy.","zh-TW":"她贊成彈性工作政策。"}]', 'prepositional phrase'),
('at the forefront of', '處於…的最前沿；引領', 'leading or most advanced in a field', '[{"en":"This company is at the forefront of AI research.","zh-TW":"這家公司處於人工智慧研究的最前沿。"},{"en":"She put her team at the forefront of industry change.","zh-TW":"她讓團隊站在行業變革的最前沿。"}]', 'prepositional phrase'),
('in conjunction with', '與…一起；配合', 'together with or in combination with', '[{"en":"This tool works best in conjunction with our CRM system.","zh-TW":"此工具與我們的CRM系統配合使用效果最佳。"},{"en":"The campaign was launched in conjunction with the product release.","zh-TW":"該活動與產品發布同時推出。"}]', 'prepositional phrase'),
('in the interest of', '為了…的利益；符合…的利益', 'for the benefit of or to help achieve', '[{"en":"In the interest of transparency we disclosed all costs.","zh-TW":"為了透明起見我們披露了所有費用。"},{"en":"The decision was made in the interest of all stakeholders.","zh-TW":"該決定是為了所有利益相關者的利益而做出的。"}]', 'prepositional phrase'),
('subsequent to', '在…之後；隨後', 'coming after something in time or order', '[{"en":"Subsequent to the audit corrective actions were taken.","zh-TW":"審計之後採取了糾正措施。"},{"en":"Subsequent to the meeting minutes will be distributed.","zh-TW":"會議之後將分發會議記錄。"}]', 'prepositional phrase'),
('back to the drawing board', '重頭再來；重新規劃', 'start over because the current plan failed', '[{"en":"After client rejection it was back to the drawing board.","zh-TW":"客戶拒絕後只好重頭再來。"},{"en":"We went back to the drawing board on the product design.","zh-TW":"我們重新規劃了產品設計。"}]', 'business idiom'),
('in the red', '虧損；赤字', 'spending more money than you earn; in debt', '[{"en":"The division has been in the red for two quarters.","zh-TW":"該部門連續兩個季度處於虧損狀態。"},{"en":"If costs rise further we will be in the red.","zh-TW":"若成本繼續上升我們將陷入虧損。"}]', 'business idiom'),
('in the black', '盈利；財務健康', 'making a profit; having a positive balance', '[{"en":"After restructuring the company is finally in the black.","zh-TW":"重組後公司終於扭虧為盈。"},{"en":"Our goal is to stay in the black throughout the year.","zh-TW":"我們的目標是全年保持盈利。"}]', 'business idiom'),
('hit the ground running', '迅速投入工作；立即高效運作', 'to start working immediately and energetically', '[{"en":"The new hire hit the ground running from day one.","zh-TW":"新員工從第一天就立即高效投入工作。"},{"en":"We need to hit the ground running after the holiday.","zh-TW":"假期後我們需要立即全速投入工作。"}]', 'business idiom'),
('move the needle', '產生顯著影響；推動進展', 'to make a noticeable change or impact', '[{"en":"This campaign really moved the needle on brand awareness.","zh-TW":"這次活動大幅提升了品牌知名度。"},{"en":"We need ideas that truly move the needle.","zh-TW":"我們需要能真正產生重大影響的想法。"}]', 'business idiom'),
('take it offline', '私下再討論；會後再談', 'to continue a discussion separately from the main meeting', '[{"en":"Let us take this offline and avoid delaying the meeting.","zh-TW":"我們把這個留到會後再談，避免耽誤會議。"},{"en":"I suggest we take the budget debate offline.","zh-TW":"我建議把預算辯論留到私下討論。"}]', 'business idiom'),
('crunch the numbers', '計算數據；分析數字', 'to perform mathematical calculations or analyze data', '[{"en":"I need time to crunch the numbers before deciding.","zh-TW":"我需要時間計算數據再做決定。"},{"en":"The finance team crunched the numbers overnight.","zh-TW":"財務團隊通宵分析了數字。"}]', 'business idiom'),
('have skin in the game', '在其中有利益；有切身利益', 'to have a personal financial or risk stake in an outcome', '[{"en":"Investors want founders who have skin in the game.","zh-TW":"投資者希望創始人在其中有切身利益。"},{"en":"He has skin in the game so he is motivated to succeed.","zh-TW":"他在其中有利益所以有動力成功。"}]', 'business idiom'),
('synergy', '協同效應；相輔相成', 'the combined effect being greater than individual parts', '[{"en":"The merger was expected to create synergy across departments.","zh-TW":"這次合併預計將在各部門間產生協同效應。"},{"en":"We look for synergy between our services and client needs.","zh-TW":"我們尋求服務與客戶需求之間的協同效應。"}]', 'business idiom'),
('sign off on', '正式批准；簽字同意', 'to give formal approval to something', '[{"en":"The manager needs to sign off on all expense reports.","zh-TW":"所有費用報告都需要主管簽字批准。"},{"en":"Has the legal team signed off on the contract?","zh-TW":"法務團隊已批准合同了嗎？"}]', 'phrasal verb'),
('run by', '向…徵詢意見；請某人審閱', 'to tell someone about something to get their opinion', '[{"en":"Let me run this proposal by the legal team.","zh-TW":"讓我先請法務團隊審閱這份提案。"},{"en":"Can you run this idea by the director before we proceed?","zh-TW":"在繼續之前你能先請總監審閱這個想法嗎？"}]', 'phrasal verb'),
('factor in', '將…納入考量；考慮在內', 'to include something as a factor in calculations or plans', '[{"en":"We need to factor in the shipping costs.","zh-TW":"我們需要將運費納入考量。"},{"en":"Did you factor in the risk of currency fluctuation?","zh-TW":"你考慮到匯率波動的風險了嗎？"}]', 'phrasal verb'),
('zero in on', '聚焦於；鎖定', 'to focus closely on a target or issue', '[{"en":"The team zeroed in on the root cause of the defect.","zh-TW":"團隊鎖定了缺陷的根本原因。"},{"en":"We need to zero in on our target demographic.","zh-TW":"我們需要聚焦於目標客群。"}]', 'phrasal verb'),
('capitalize on', '善加利用；抓住機會', 'to take advantage of an opportunity or strength', '[{"en":"We must capitalize on this market trend.","zh-TW":"我們必須善加利用這個市場趨勢。"},{"en":"She capitalized on her network to win the deal.","zh-TW":"她善用人脈贏得了這筆交易。"}]', 'phrasal verb'),
('bounce back', '反彈；恢復', 'to recover quickly after a setback', '[{"en":"The company bounced back after a difficult quarter.","zh-TW":"公司在艱困的季度後迅速反彈。"},{"en":"She bounced back from the failed launch and tried again.","zh-TW":"她從失敗的發布中恢復並再次嘗試。"}]', 'phrasal verb'),
('bring forward', '提前；提出', 'to move to an earlier time, or to put forward a proposal', '[{"en":"They brought the deadline forward by one week.","zh-TW":"他們將截止日期提前了一週。"},{"en":"She brought forward a new idea at the annual review.","zh-TW":"她在年度審查中提出了一個新想法。"}]', 'phrasal verb'),
('push back', '推遲；抵制；反駁', 'to delay or express opposition to something', '[{"en":"The client pushed back on the pricing proposal.","zh-TW":"客戶對定價提案提出了反駁。"},{"en":"We had to push back the product launch date.","zh-TW":"我們不得不推遲產品發布日期。"}]', 'phrasal verb'),
('tie up', '佔用；完成最後細節', 'to occupy fully, or to finalize loose ends', '[{"en":"Let us tie up any loose ends before the client visit.","zh-TW":"在客戶來訪前讓我們把所有細節都處理好。"},{"en":"Too much capital is tied up in unsold inventory.","zh-TW":"太多資金被積壓在未售庫存中。"}]', 'phrasal verb'),
('roll back', '撤回；回滾；降低', 'to reverse or reduce something previously set', '[{"en":"The government rolled back tariffs on imported goods.","zh-TW":"政府降低了進口商品的關稅。"},{"en":"They had to roll back the software update due to bugs.","zh-TW":"由於存在錯誤他們不得不回滾軟體更新。"}]', 'phrasal verb'),
('opt out of', '選擇退出；不參與', 'to choose not to participate in something', '[{"en":"Employees can opt out of the pension scheme.","zh-TW":"員工可以選擇退出養老金計劃。"},{"en":"Several partners opted out of the joint venture.","zh-TW":"幾個合作夥伴選擇退出了合資企業。"}]', 'phrasal verb'),
('head up', '領導；主持', 'to lead or be in charge of a group or project', '[{"en":"She will head up the new sustainability initiative.","zh-TW":"她將主持新的永續發展計劃。"},{"en":"He heads up our Asia-Pacific operations.","zh-TW":"他領導我們的亞太區業務。"}]', 'phrasal verb'),
('flag up', '標記；提出（問題）', 'to draw attention to or highlight an issue', '[{"en":"Please flag up any potential risks early.","zh-TW":"請及早提出任何潛在風險。"},{"en":"The auditor flagged up several compliance issues.","zh-TW":"審計員標記了幾個合規問題。"}]', 'phrasal verb'),
('chip in', '插嘴；貢獻一份力量；共同分擔', 'to contribute a share or add a comment', '[{"en":"Everyone chipped in to cover the project costs.","zh-TW":"大家各出一份力分擔了專案費用。"},{"en":"She chipped in with a great idea during the brainstorm.","zh-TW":"她在腦力激盪中提出了一個很好的想法。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('hammer out', '反覆協商達成；艱難制定', 'to reach an agreement through lengthy negotiation', '[{"en":"Both parties hammered out a deal after lengthy talks.","zh-TW":"雙方經過長時間談判終於達成了協議。"},{"en":"We need to hammer out the final terms of the contract.","zh-TW":"我們需要艱難地敲定合同的最終條款。"}]', 'phrasal verb'),
('tap into', '挖掘；利用（資源或市場）', 'to access or make use of a resource or market', '[{"en":"We plan to tap into the emerging Asian markets.","zh-TW":"我們計劃進入新興亞洲市場。"},{"en":"The app taps into user data to personalize recommendations.","zh-TW":"該應用程式利用用戶數據來個性化推薦。"}]', 'phrasal verb'),
('map out', '規劃；制定詳細計劃', 'to plan in detail or create a structured outline', '[{"en":"We mapped out the entire project timeline.","zh-TW":"我們詳細規劃了整個專案時間表。"},{"en":"She mapped out the steps needed to reach the goal.","zh-TW":"她規劃了達成目標所需的每個步驟。"}]', 'phrasal verb'),
('work around', '繞過；想辦法解決', 'to find a way to avoid or deal with a problem', '[{"en":"We found a way to work around the technical limitation.","zh-TW":"我們找到了繞過技術限制的方法。"},{"en":"Can you work around the schedule conflict?","zh-TW":"你能想辦法解決排程衝突嗎？"}]', 'phrasal verb'),
('at a crossroads', '處於十字路口；面臨抉擇', 'at a point where an important decision must be made', '[{"en":"The company is at a crossroads and must choose its path.","zh-TW":"公司處於十字路口必須選擇方向。"},{"en":"She felt at a crossroads after the merger announcement.","zh-TW":"並購宣布後她感到自己面臨抉擇。"}]', 'expression'),
('play it by ear', '隨機應變；見機行事', 'to proceed without a fixed plan; to improvise', '[{"en":"We do not have a set agenda so let us play it by ear.","zh-TW":"我們沒有固定議程就隨機應變吧。"},{"en":"Given the uncertainty she decided to play it by ear.","zh-TW":"鑑於不確定性她決定見機行事。"}]', 'expression'),
('hold your ground', '堅持立場；不退讓', 'to maintain your position under pressure', '[{"en":"In the negotiation she held her ground on the price.","zh-TW":"在談判中她堅持了自己的定價立場。"},{"en":"Hold your ground even when clients push back.","zh-TW":"即使客戶反對也要堅持立場。"}]', 'expression'),
('in the loop', '了解最新情況；在知情範圍內', 'kept informed about what is happening', '[{"en":"Please keep me in the loop on any developments.","zh-TW":"請讓我隨時了解任何進展。"},{"en":"She made sure all stakeholders were in the loop.","zh-TW":"她確保所有利益相關者都掌握最新資訊。"}]', 'expression'),
('out of the loop', '不知情；被排除在外', 'not informed about recent developments', '[{"en":"I felt out of the loop after missing the key meetings.","zh-TW":"錯過關鍵會議後我感到不知情。"},{"en":"She was left out of the loop on the strategic decision.","zh-TW":"她被排除在策略決策的知情範圍之外。"}]', 'expression'),
('take the lead', '帶頭；主導', 'to take primary responsibility or initiative', '[{"en":"He took the lead on the client presentation.","zh-TW":"他主導了客戶簡報。"},{"en":"We need someone to take the lead on this initiative.","zh-TW":"我們需要有人帶頭推動這個計劃。"}]', 'expression'),
('across the board', '全面；普遍', 'applying to all cases or categories equally', '[{"en":"Salaries were increased across the board this year.","zh-TW":"今年全面提高了薪資。"},{"en":"Performance improved across the board after training.","zh-TW":"培訓後各方面表現全面提升。"}]', 'expression'),
('on the cards', '很可能發生；在預料之中', 'likely to happen; predicted', '[{"en":"A restructuring has been on the cards for months.","zh-TW":"重組已在預料之中好幾個月了。"},{"en":"A price increase seems to be on the cards.","zh-TW":"漲價似乎很可能發生。"}]', 'expression'),
('put something on the back burner', '暫緩；擱置', 'to give something lower priority temporarily', '[{"en":"We put the expansion plan on the back burner for now.","zh-TW":"我們暫時把擴張計劃擱置了。"},{"en":"That idea is on the back burner until we have more funding.","zh-TW":"那個想法在獲得更多資金之前暫時擱置。"}]', 'expression'),
('a blessing in disguise', '因禍得福；塞翁失馬', 'something that seems bad but turns out to be good', '[{"en":"The contract loss was a blessing in disguise — it freed resources.","zh-TW":"失去那份合同因禍得福，讓我們釋放了資源。"},{"en":"The delay proved to be a blessing in disguise.","zh-TW":"這次延誤最終因禍得福。"}]', 'expression'),
('pull strings', '動用關係；幕後操控', 'to use personal influence to get things done', '[{"en":"He pulled strings to secure the government contract.","zh-TW":"他動用關係拿到了政府合同。"},{"en":"She does not like to pull strings to advance her career.","zh-TW":"她不喜歡動用關係來推進自己的職業生涯。"}]', 'expression'),
('get the green light', '獲得批准；得到許可', 'to receive approval to proceed with something', '[{"en":"The project got the green light from senior management.","zh-TW":"專案獲得了高層管理的批准。"},{"en":"Once we get the green light we can start immediately.","zh-TW":"一旦獲得批准我們可以立即開始。"}]', 'expression'),
('push the envelope', '突破極限；開拓疆界', 'to go beyond what is conventional or previously possible', '[{"en":"This product pushes the envelope of modern design.","zh-TW":"這款產品突破了現代設計的極限。"},{"en":"Our team is known for pushing the envelope.","zh-TW":"我們的團隊以突破常規著稱。"}]', 'expression'),
('take the bull by the horns', '勇敢面對；迎難而上', 'to confront a difficult problem directly and decisively', '[{"en":"She took the bull by the horns and addressed the budget shortfall.","zh-TW":"她勇敢面對並解決了預算缺口問題。"},{"en":"It is time to take the bull by the horns on this issue.","zh-TW":"是時候迎難而上解決這個問題了。"}]', 'expression'),
('have a lot on one''s plate', '事情繁多；工作量很大', 'to have many tasks or responsibilities to deal with', '[{"en":"She has a lot on her plate with three projects running.","zh-TW":"她同時運作三個專案，工作量很大。"},{"en":"I have a lot on my plate this week but I will manage.","zh-TW":"我這週事情很多但我會設法處理。"}]', 'expression'),
('in view of', '考慮到；鑑於', 'considering or in light of a particular situation', '[{"en":"In view of budget constraints we downsized the event.","zh-TW":"考慮到預算限制我們縮小了活動規模。"},{"en":"In view of the positive results we will continue the campaign.","zh-TW":"鑑於正面結果我們將繼續這次活動。"}]', 'prepositional phrase'),
('by means of', '藉由；透過', 'using a particular method or tool', '[{"en":"We resolved the issue by means of direct negotiation.","zh-TW":"我們藉由直接談判解決了問題。"},{"en":"Communication was maintained by means of video calls.","zh-TW":"透過視訊通話維持了溝通。"}]', 'prepositional phrase'),
('in pursuit of', '追求；為了實現', 'in the process of trying to achieve or obtain', '[{"en":"In pursuit of excellence we raised our standards.","zh-TW":"為了追求卓越我們提高了標準。"},{"en":"She travelled overseas in pursuit of business opportunities.","zh-TW":"她出國是為了尋求商業機會。"}]', 'prepositional phrase'),
('at the heart of', '在…的核心；最重要的部分', 'at the most important or central part of something', '[{"en":"Customer trust is at the heart of our business model.","zh-TW":"客戶信任是我們商業模式的核心。"},{"en":"At the heart of the problem is a lack of communication.","zh-TW":"問題的核心是缺乏溝通。"}]', 'prepositional phrase'),
('on the verge of', '即將；在…邊緣', 'very close to happening or doing something', '[{"en":"The startup is on the verge of its first major deal.","zh-TW":"新創公司即將完成第一筆重大交易。"},{"en":"They were on the verge of bankruptcy before the bailout.","zh-TW":"在救援前他們瀕臨破產邊緣。"}]', 'prepositional phrase'),
('in spite of', '儘管；不管', 'without being prevented by something; despite', '[{"en":"In spite of setbacks the project was completed on time.","zh-TW":"儘管有挫折，專案仍按時完成。"},{"en":"She succeeded in spite of limited resources.","zh-TW":"儘管資源有限她仍然成功了。"}]', 'prepositional phrase'),
('in contrast to', '與…相比；相比之下', 'when compared with something very different', '[{"en":"In contrast to last year profits have grown significantly.","zh-TW":"與去年相比利潤大幅增長。"},{"en":"In contrast to the competition we focus on quality.","zh-TW":"與競爭對手相比我們專注於品質。"}]', 'prepositional phrase'),
('in addition to', '除了…之外；再加上', 'as well as; also', '[{"en":"In addition to the salary we offer a generous bonus.","zh-TW":"除薪資外我們還提供豐厚的獎金。"},{"en":"In addition to English she speaks three other languages.","zh-TW":"除英語外她還會說三種其他語言。"}]', 'prepositional phrase'),
('in advance of', '在…之前；提前', 'before a particular time or event', '[{"en":"Please submit your report in advance of the meeting.","zh-TW":"請在會議前提前提交報告。"},{"en":"We ordered supplies in advance of the busy season.","zh-TW":"我們在旺季前提前訂購了物資。"}]', 'prepositional phrase'),
('with a view to', '為了；以…為目標', 'with the intention or goal of doing something', '[{"en":"She took the certification with a view to advancing her career.","zh-TW":"她取得認證是為了推進職業發展。"},{"en":"They partnered with a view to entering the Asian market.","zh-TW":"他們合作是為了進軍亞洲市場。"}]', 'prepositional phrase'),
('at the disposal of', '供…使用；任…支配', 'available for someone to use freely', '[{"en":"All resources are at the disposal of the project manager.","zh-TW":"所有資源都供專案經理使用。"},{"en":"Our technical support is at your disposal.","zh-TW":"我們的技術支援任您差遣。"}]', 'prepositional phrase'),
('under the supervision of', '在…的監督下', 'managed or watched over by someone', '[{"en":"Interns work under the supervision of senior staff.","zh-TW":"實習生在資深員工的監督下工作。"},{"en":"The trial was conducted under the supervision of experts.","zh-TW":"試驗在專家的監督下進行。"}]', 'prepositional phrase'),
('by way of', '作為；透過；途經', 'as a form of, or passing through', '[{"en":"By way of introduction let me explain our background.","zh-TW":"作為介紹讓我說明一下我們的背景。"},{"en":"She offered a discount by way of apology.","zh-TW":"她提供折扣作為道歉。"}]', 'prepositional phrase'),
('put all eggs in one basket', '孤注一擲；把所有賭注押在一件事上', 'to risk everything on a single plan or option', '[{"en":"Diversify to avoid putting all your eggs in one basket.","zh-TW":"要多元化以避免孤注一擲。"},{"en":"He put all his eggs in one basket with that investment.","zh-TW":"他把所有賭注押在那項投資上。"}]', 'business idiom'),
('a foot in the door', '打入市場；初步接觸', 'an initial position or first step toward a goal', '[{"en":"Internships can give you a foot in the door.","zh-TW":"實習可以讓你打入職場大門。"},{"en":"We got a foot in the door with a small pilot contract.","zh-TW":"我們通過一個小型試點合同打入了市場。"}]', 'business idiom'),
('cut to the chase', '直入主題；開門見山', 'to get to the main point without wasting time', '[{"en":"Let us cut to the chase — what is your budget?","zh-TW":"開門見山吧——你的預算是多少？"},{"en":"She cut to the chase and presented the key findings.","zh-TW":"她直入主題呈現了關鍵發現。"}]', 'business idiom'),
('bring to the table', '貢獻；帶來；提供', 'to contribute skills or value to a discussion or deal', '[{"en":"What experience can you bring to the table?","zh-TW":"你能帶來什麼樣的經驗？"},{"en":"She brings extensive global expertise to the table.","zh-TW":"她帶來了豐富的全球專業知識。"}]', 'business idiom'),
('fast track', '快速通道；加快進展', 'an accelerated path to completion or promotion', '[{"en":"This programme puts graduates on the fast track.","zh-TW":"這個計劃讓畢業生走上快速發展之路。"},{"en":"The project was fast-tracked due to urgency.","zh-TW":"由於緊迫性，專案被加快了進度。"}]', 'business idiom'),
('blue-sky thinking', '天馬行空的創意思維；無約束的創新', 'unrestricted, creative, and innovative thinking', '[{"en":"The workshop encouraged blue-sky thinking about the future.","zh-TW":"研討會鼓勵對未來進行天馬行空的創意思考。"},{"en":"We need blue-sky thinking to disrupt the market.","zh-TW":"我們需要創新思維來顛覆市場。"}]', 'business idiom'),
('get the ball in someone''s court', '讓對方做決定；把責任交給對方', 'to make it the other person''s responsibility to act', '[{"en":"We submitted the proposal — the ball is in their court now.","zh-TW":"我們提交了提案——現在輪到他們決定了。"},{"en":"She responded to put the ball back in their court.","zh-TW":"她做出了回應，把決定權還給了對方。"}]', 'business idiom'),
('window of opportunity', '良機；機會之窗', 'a limited time period in which action is possible', '[{"en":"We have a narrow window of opportunity to enter the market.","zh-TW":"我們有一個狹窄的良機可以進入市場。"},{"en":"Act now before the window of opportunity closes.","zh-TW":"趁機會還在趕快行動。"}]', 'business idiom'),
('keep the ball rolling', '保持進展；持續推動', 'to maintain momentum or progress in an activity', '[{"en":"Good communication helps keep the ball rolling.","zh-TW":"良好溝通有助於保持進展。"},{"en":"We need weekly check-ins to keep the ball rolling.","zh-TW":"我們需要每週檢查以維持專案動力。"}]', 'business idiom'),
('throw in the towel', '投降；認輸；放棄', 'to give up and admit defeat', '[{"en":"Despite setbacks we refused to throw in the towel.","zh-TW":"儘管遇到挫折我們拒絕放棄。"},{"en":"They threw in the towel after the third failed attempt.","zh-TW":"第三次失敗後他們認輸了。"}]', 'business idiom'),
('hit a wall', '碰壁；遭遇瓶頸', 'to encounter an obstacle that stops progress', '[{"en":"We hit a wall when negotiations stalled.","zh-TW":"談判停滯時我們遭遇了瓶頸。"},{"en":"The development team hit a wall with the new architecture.","zh-TW":"開發團隊在新架構方面遭遇了障礙。"}]', 'business idiom'),
('give the go-ahead', '給予批准；同意開始', 'to approve the start of something', '[{"en":"The board gave the go-ahead for the new factory.","zh-TW":"董事會批准了新工廠的建設。"},{"en":"Once we receive the go-ahead we will proceed.","zh-TW":"一旦收到批准我們就會推進。"}]', 'business idiom'),
('play hardball', '採取強硬立場；不讓步', 'to use tough tactics in negotiations or dealings', '[{"en":"They played hardball and refused to lower the price.","zh-TW":"他們採取強硬立場拒絕降價。"},{"en":"She knew when to play hardball to win better terms.","zh-TW":"她知道何時採取強硬立場以爭取更好的條款。"}]', 'business idiom'),
('behind the eight ball', '處於不利處境；進退兩難', 'in a difficult or unfavorable position', '[{"en":"With two missed deadlines we are behind the eight ball.","zh-TW":"錯過兩個截止日期後我們陷入了不利處境。"},{"en":"They found themselves behind the eight ball after the recall.","zh-TW":"召回事件後他們發現自己進退兩難。"}]', 'business idiom'),
('ahead of schedule', '提前於計劃；進度超前', 'completing work earlier than the planned timeline', '[{"en":"The project is two weeks ahead of schedule.","zh-TW":"專案比計劃提前了兩週。"},{"en":"They delivered the product ahead of schedule.","zh-TW":"他們提前交付了產品。"}]', 'business idiom'),
('speak out', '大聲說出；公開表態', 'to express opinions publicly or loudly', '[{"en":"She spoke out against the unfair policy.","zh-TW":"她公開反對這項不公平的政策。"},{"en":"Employees should feel free to speak out about problems.","zh-TW":"員工應該能夠自由表達問題。"}]', 'phrasal verb'),
('lay out', '陳列；說明；制定佈局', 'to present or arrange clearly', '[{"en":"She laid out the proposal clearly in the presentation.","zh-TW":"她在簡報中清晰地陳述了提案。"},{"en":"Let me lay out the timeline for this project.","zh-TW":"讓我說明這個專案的時間表。"}]', 'phrasal verb'),
('follow through', '貫徹到底；跟進落實', 'to complete an action that was started or promised', '[{"en":"It is important to follow through on your commitments.","zh-TW":"貫徹你的承諾非常重要。"},{"en":"She followed through on every promise she made.","zh-TW":"她兌現了自己做出的每個承諾。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('get behind', '支持；全力投入', 'to support or commit to something enthusiastically', '[{"en":"The whole team got behind the new direction.","zh-TW":"整個團隊都全力支持新方向。"},{"en":"Management needs to get behind this initiative.","zh-TW":"管理層需要支持這項計劃。"}]', 'phrasal verb'),
('stand by', '支持；準備就緒；堅守', 'to support, or to be ready and waiting', '[{"en":"I stand by our decision to expand.","zh-TW":"我堅守我們擴張的決定。"},{"en":"Please stand by for further instructions.","zh-TW":"請準備就緒等待進一步指示。"}]', 'phrasal verb'),
('follow up on', '跟進；後續追蹤', 'to check on progress or continue an action', '[{"en":"I will follow up on this issue with the team tomorrow.","zh-TW":"我明天會跟團隊跟進這個問題。"},{"en":"She followed up on the client inquiry the same day.","zh-TW":"她當天就跟進了客戶的詢問。"}]', 'phrasal verb'),
('give way to', '讓步給；被…取代', 'to be replaced by or yield to something', '[{"en":"Traditional processes gave way to digital solutions.","zh-TW":"傳統流程被數位解決方案所取代。"},{"en":"She gave way to pressure and revised the timeline.","zh-TW":"她在壓力下讓步並修訂了時間表。"}]', 'phrasal verb'),
('hold off', '推遲；暫緩；阻止', 'to delay or wait before doing something', '[{"en":"Let us hold off on the announcement until next week.","zh-TW":"讓我們把公告推遲到下週。"},{"en":"She held off the investors with a new timeline.","zh-TW":"她用新的時間表暫緩了投資者的要求。"}]', 'phrasal verb'),
('turn around', '扭轉局面；轉身；完成周轉', 'to reverse a negative situation or complete a task quickly', '[{"en":"The new CEO managed to turn the company around.","zh-TW":"新任執行長成功扭轉了公司的局面。"},{"en":"Can you turn around this report by tomorrow?","zh-TW":"你能在明天前完成這份報告嗎？"}]', 'phrasal verb'),
('take stock of', '評估；盤點', 'to carefully assess a situation or inventory', '[{"en":"Before planning we need to take stock of our current resources.","zh-TW":"規劃前我們需要評估目前的資源狀況。"},{"en":"She took stock of the situation and decided to pivot.","zh-TW":"她評估了情況後決定轉型。"}]', 'phrasal verb'),
('pull through', '度過難關；恢復', 'to survive a difficult situation or recover', '[{"en":"The company pulled through the financial crisis.","zh-TW":"公司度過了金融危機。"},{"en":"With the team''s support the project pulled through.","zh-TW":"在團隊支持下專案度過了難關。"}]', 'phrasal verb'),
('bring in', '引進；帶入；創造收入', 'to introduce or earn a certain amount', '[{"en":"The new service brought in significant revenue.","zh-TW":"新服務帶來了可觀的收入。"},{"en":"We brought in an external consultant to review our processes.","zh-TW":"我們引進了外部顧問來審查我們的流程。"}]', 'phrasal verb'),
('hand over', '移交；交接', 'to transfer control or responsibility to someone else', '[{"en":"She handed over the project to her successor.","zh-TW":"她將專案移交給了繼任者。"},{"en":"Please hand over the files before you leave.","zh-TW":"離開前請移交文件。"}]', 'phrasal verb'),
('set aside', '撥出；保留；擱置爭議', 'to reserve for a specific purpose or ignore temporarily', '[{"en":"We set aside funds for emergency repairs.","zh-TW":"我們為緊急維修撥出了資金。"},{"en":"Let us set aside our differences and focus on the goal.","zh-TW":"讓我們擱置分歧並專注於目標。"}]', 'phrasal verb'),
('measure up', '達到標準；符合期望', 'to meet expectations or required standards', '[{"en":"Does the new vendor measure up to our requirements?","zh-TW":"新供應商能符合我們的要求嗎？"},{"en":"The product did not measure up to the specifications.","zh-TW":"這款產品未能達到規格要求。"}]', 'phrasal verb'),
('pick up on', '注意到；察覺；接受', 'to notice or become aware of something', '[{"en":"She picked up on the tension in the meeting.","zh-TW":"她察覺到了會議中的緊張氣氛。"},{"en":"Our analysts picked up on the emerging market trend.","zh-TW":"我們的分析師注意到了新興市場趨勢。"}]', 'phrasal verb'),
('give out', '分發；精疲力竭；停止運作', 'to distribute, or to stop working properly', '[{"en":"Please give out the meeting agenda to all attendees.","zh-TW":"請將會議議程分發給所有與會者。"},{"en":"The system gave out during peak hours.","zh-TW":"系統在高峰時段停止了運作。"}]', 'phrasal verb'),
('spill the beans', '洩露秘密；說漏嘴', 'to reveal a secret or confidential information', '[{"en":"Someone spilled the beans about the product launch.","zh-TW":"有人洩露了產品發布的秘密。"},{"en":"Do not spill the beans before the official announcement.","zh-TW":"在正式公告前不要說漏嘴。"}]', 'expression'),
('go back to basics', '回歸基本；從基礎開始', 'to return to fundamental principles', '[{"en":"When results drop it is time to go back to basics.","zh-TW":"當成果下滑時是時候回歸基本了。"},{"en":"She advised the team to go back to basics with customer service.","zh-TW":"她建議團隊在客服方面回歸基本原則。"}]', 'expression'),
('show the ropes', '傳授訣竅；指導新人', 'to teach someone how things are done', '[{"en":"Could you show the new intern the ropes?","zh-TW":"你能指導一下新實習生嗎？"},{"en":"He showed her the ropes during her first week.","zh-TW":"她入職第一週他傳授了她訣竅。"}]', 'expression'),
('beat around the bush', '拐彎抹角；避而不談', 'to avoid talking about the main subject directly', '[{"en":"Stop beating around the bush and tell us the budget.","zh-TW":"別再拐彎抹角了，直接告訴我們預算吧。"},{"en":"She was beating around the bush during the negotiation.","zh-TW":"她在談判中拐彎抹角。"}]', 'expression'),
('draw a line in the sand', '劃定底線；設下不可逾越的界限', 'to set a firm limit that cannot be crossed', '[{"en":"Management drew a line in the sand on discount levels.","zh-TW":"管理層劃定了折扣底線。"},{"en":"She drew a line in the sand regarding overtime work.","zh-TW":"她對加班問題劃定了界限。"}]', 'expression'),
('on thin ice', '如履薄冰；處境危險', 'in a risky or precarious situation', '[{"en":"After missing three deadlines he is on thin ice.","zh-TW":"錯過三個截止日期後他如履薄冰。"},{"en":"Be careful — you are on thin ice with the client.","zh-TW":"小心——你與客戶的關係處於危險邊緣。"}]', 'expression'),
('go the extra mile', '加倍努力；付出額外心力', 'to do more than what is required or expected', '[{"en":"She always goes the extra mile for her clients.","zh-TW":"她總是為客戶付出額外的心力。"},{"en":"Going the extra mile sets us apart from the competition.","zh-TW":"加倍努力讓我們有別於競爭者。"}]', 'expression'),
('pass the buck', '推卸責任；推諉', 'to blame someone else or transfer responsibility', '[{"en":"Stop passing the buck — own the mistake and fix it.","zh-TW":"別再推卸責任了——承認錯誤並解決它。"},{"en":"The issue escalated because everyone was passing the buck.","zh-TW":"問題惡化是因為每個人都在推諉。"}]', 'expression'),
('call the shots', '做主；拍板決定', 'to be the person in control who makes decisions', '[{"en":"As CEO she calls the shots on major decisions.","zh-TW":"身為執行長她對重大決策拍板做主。"},{"en":"Who calls the shots in your organization?","zh-TW":"你們組織裡誰做主決策？"}]', 'expression'),
('close ranks', '團結一致；共同面對', 'to unite in support against a common challenge', '[{"en":"The team closed ranks in the face of media criticism.","zh-TW":"面對媒體批評團隊團結一致。"},{"en":"Management closed ranks to protect the company''s reputation.","zh-TW":"管理層齊心協力保護公司聲譽。"}]', 'expression'),
('ring a bell', '似乎耳熟；讓人想起', 'to seem familiar or remind someone of something', '[{"en":"Does the company name ring a bell?","zh-TW":"這個公司名字你聽起來耳熟嗎？"},{"en":"The client''s description rings a bell from last year.","zh-TW":"客戶的描述讓我想起了去年的事。"}]', 'expression'),
('come to a head', '達到頂點；情況趨於嚴峻', 'to reach a critical point where action must be taken', '[{"en":"The conflict came to a head during the board meeting.","zh-TW":"衝突在董事會會議上達到了頂點。"},{"en":"The budget dispute finally came to a head.","zh-TW":"預算爭議終於到了需要解決的關頭。"}]', 'expression'),
('bridge the gap', '縮小差距；彌合分歧', 'to reduce the difference between two things', '[{"en":"We need to bridge the gap between sales and operations.","zh-TW":"我們需要縮小銷售與運營之間的差距。"},{"en":"This training programme bridges the skills gap.","zh-TW":"這個培訓計劃填補了技能差距。"}]', 'expression'),
('have a stake in', '在…中有利益；與…有利害關係', 'to have a financial or personal interest in something', '[{"en":"Every employee has a stake in the company''s success.","zh-TW":"每位員工都與公司的成功有利害關係。"},{"en":"Investors have a stake in how this project performs.","zh-TW":"投資者在這個專案的表現上有切身利益。"}]', 'expression'),
('eat into', '侵蝕；蠶食；佔用', 'to reduce or use up gradually', '[{"en":"Rising costs are eating into our profit margins.","zh-TW":"不斷上漲的成本正在蠶食我們的利潤空間。"},{"en":"These meetings are eating into valuable work time.","zh-TW":"這些會議正在佔用寶貴的工作時間。"}]', 'expression'),
('at a premium', '以高價；很搶手', 'at a higher price than usual, or in short supply', '[{"en":"Office space in the city center is at a premium.","zh-TW":"市中心的辦公空間非常搶手。"},{"en":"This limited edition product is sold at a premium.","zh-TW":"這款限量版產品以高價出售。"}]', 'prepositional phrase'),
('at a glance', '一眼便知；一目了然', 'immediately or easily understood upon first look', '[{"en":"The dashboard shows key metrics at a glance.","zh-TW":"儀表板一目了然地顯示關鍵指標。"},{"en":"You can tell at a glance whether the status is green.","zh-TW":"你一眼就能看出狀態是否為綠色。"}]', 'prepositional phrase'),
('at odds with', '與…不一致；與…對立', 'in conflict or disagreement with', '[{"en":"His approach was at odds with company policy.","zh-TW":"他的做法與公司政策不一致。"},{"en":"The survey results were at odds with our assumptions.","zh-TW":"調查結果與我們的假設相悖。"}]', 'prepositional phrase'),
('in line with', '與…一致；符合', 'consistent with or following a rule or expectation', '[{"en":"The price increase is in line with market trends.","zh-TW":"此次漲價與市場趨勢一致。"},{"en":"Results were in line with our annual forecast.","zh-TW":"結果與我們的年度預測一致。"}]', 'prepositional phrase'),
('in excess of', '超過；多於', 'more than a specified amount or level', '[{"en":"Revenue grew in excess of 20% this year.","zh-TW":"今年收入增長超過了20%。"},{"en":"The project costs were in excess of the original estimate.","zh-TW":"專案費用超過了最初的估算。"}]', 'prepositional phrase'),
('in proportion to', '與…成比例；相應地', 'at a level relative or corresponding to something', '[{"en":"Bonuses are awarded in proportion to performance.","zh-TW":"獎金按績效比例發放。"},{"en":"Resources are allocated in proportion to project size.","zh-TW":"資源按專案規模比例分配。"}]', 'prepositional phrase'),
('subject to', '受制於；以…為前提', 'dependent on or likely to be affected by something', '[{"en":"This offer is subject to management approval.","zh-TW":"此報價須經管理層批准。"},{"en":"All prices are subject to change without notice.","zh-TW":"所有價格如有更改恕不另行通知。"}]', 'prepositional phrase'),
('in the wake of', '在…之後；繼…之後', 'following and as a result of something', '[{"en":"In the wake of the scandal the CEO resigned.","zh-TW":"醜聞發生後執行長辭職了。"},{"en":"New regulations emerged in the wake of the financial crisis.","zh-TW":"金融危機之後出現了新的監管法規。"}]', 'prepositional phrase'),
('in the context of', '在…背景下；就…而言', 'considering the surrounding circumstances or background', '[{"en":"In the context of globalization this strategy makes sense.","zh-TW":"在全球化的背景下這個策略是合理的。"},{"en":"The data must be read in the context of last year''s results.","zh-TW":"這些數據必須結合去年的結果來解讀。"}]', 'prepositional phrase'),
('on the grounds of', '以…為由；基於', 'because of or citing a particular reason', '[{"en":"The request was denied on the grounds of insufficient budget.","zh-TW":"請求以預算不足為由被拒絕了。"},{"en":"She was promoted on the grounds of exceptional leadership.","zh-TW":"她以卓越的領導能力為由獲得晉升。"}]', 'prepositional phrase'),
('as opposed to', '而非；與…相對', 'in contrast with or instead of', '[{"en":"We prefer direct sales as opposed to third-party channels.","zh-TW":"我們偏好直接銷售而非第三方渠道。"},{"en":"As opposed to last year revenue is now growing.","zh-TW":"與去年相比現在收入正在增長。"}]', 'prepositional phrase'),
('in isolation', '孤立地；單獨地', 'separately, without considering broader context', '[{"en":"Do not analyze this metric in isolation.","zh-TW":"不要孤立地分析這個指標。"},{"en":"The departments cannot operate in isolation.","zh-TW":"各部門不能孤立地運作。"}]', 'prepositional phrase'),
('in parallel with', '與…同步；平行進行', 'at the same time as something else', '[{"en":"Development will run in parallel with marketing preparation.","zh-TW":"開發將與行銷準備工作同步進行。"},{"en":"In parallel with cost cuts we are investing in new talent.","zh-TW":"在削減成本的同時我們正在投資新人才。"}]', 'prepositional phrase'),
('at the outset', '在開始時；最初', 'at the very beginning of something', '[{"en":"At the outset we defined clear success criteria.","zh-TW":"在開始時我們確定了明確的成功標準。"},{"en":"Set expectations at the outset to avoid confusion later.","zh-TW":"在開始時設定期望以避免後期混淆。"}]', 'prepositional phrase'),
('in full', '全額；完整地', 'completely; with nothing missing', '[{"en":"The invoice was paid in full within 30 days.","zh-TW":"發票在30天內全額付清。"},{"en":"Please read the agreement in full before signing.","zh-TW":"簽署前請完整閱讀協議。"}]', 'prepositional phrase'),
('by the book', '按規定；按章行事', 'strictly following rules and procedures', '[{"en":"Our compliance team always does things by the book.","zh-TW":"我們的合規團隊總是按規定行事。"},{"en":"He insisted on handling the audit by the book.","zh-TW":"他堅持按章程處理審計。"}]', 'prepositional phrase'),
('best of both worlds', '兩全其美；兼得', 'having the advantages of two different things simultaneously', '[{"en":"Working remotely gives us the best of both worlds.","zh-TW":"遠端工作讓我們兩全其美。"},{"en":"The hybrid model offers the best of both worlds.","zh-TW":"混合模式讓我們享受兩全其美的好處。"}]', 'business idiom'),
('add value', '增加價值；有貢獻', 'to improve something or make a positive contribution', '[{"en":"How does this feature add value for users?","zh-TW":"這個功能如何為用戶增加價值？"},{"en":"She adds value to every project she joins.","zh-TW":"她加入的每個專案都能增加價值。"}]', 'business idiom'),
('leverage', '善加利用；發揮槓桿效用', 'to use something to maximum advantage', '[{"en":"We leverage our global network to win new clients.","zh-TW":"我們善用全球網絡來開拓新客戶。"},{"en":"Leverage your existing skills to transition into this role.","zh-TW":"善用你現有的技能來轉換到這個職位。"}]', 'business idiom'),
('low-hanging fruit', '唾手可得的目標；容易實現的機會', 'easy targets or opportunities that can be achieved quickly', '[{"en":"Start with low-hanging fruit to show early results.","zh-TW":"從唾手可得的目標開始以展示早期成果。"},{"en":"The low-hanging fruit in cost saving has already been taken.","zh-TW":"成本節約方面容易實現的部分已被採用。"}]', 'business idiom'),
('bandwidth', '時間與精力；處理能力', 'the capacity or availability to handle more work', '[{"en":"I do not have the bandwidth for another project this month.","zh-TW":"這個月我沒有多餘的精力再接一個專案。"},{"en":"Do you have the bandwidth to take on this client?","zh-TW":"你有能力承接這個客戶嗎？"}]', 'business idiom');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('boil the ocean', '徒勞無功；試圖完成不可能的任務', 'to undertake an impossibly large task', '[{"en":"Do not try to boil the ocean — focus on key priorities.","zh-TW":"不要試圖做不可能的事——專注於關鍵優先事項。"},{"en":"The original scope was boiling the ocean so we cut it down.","zh-TW":"原本的範圍太過龐大所以我們縮減了。"}]', 'business idiom'),
('peel the onion', '逐層深入分析；深入研究', 'to analyze something layer by layer to find the root cause', '[{"en":"To solve this problem we need to peel the onion.","zh-TW":"要解決這個問題我們需要逐層深入分析。"},{"en":"She peeled the onion and found the real bottleneck.","zh-TW":"她逐層分析發現了真正的瓶頸所在。"}]', 'business idiom'),
('circle back', '再回來討論；稍後跟進', 'to return to a topic or conversation later', '[{"en":"Let us circle back to that question after the break.","zh-TW":"休息後讓我們再回到那個問題。"},{"en":"I will circle back with you once I have more information.","zh-TW":"等我有更多資訊後再回來跟你討論。"}]', 'business idiom'),
('deep dive', '深入分析；詳細調查', 'a thorough, in-depth examination of a topic', '[{"en":"We need to do a deep dive into the customer data.","zh-TW":"我們需要對客戶數據進行深入分析。"},{"en":"The consultant did a deep dive on our supply chain.","zh-TW":"顧問對我們的供應鏈進行了深入調查。"}]', 'business idiom'),
('pivot', '轉型；轉向；調整策略', 'to change direction or strategy significantly', '[{"en":"The startup pivoted to a subscription model.","zh-TW":"新創公司轉型為訂閱模式。"},{"en":"After the market shift they pivoted their entire strategy.","zh-TW":"市場轉變後他們調整了整個策略。"}]', 'business idiom'),
('scalable', '可擴展的；可規模化的', 'capable of growing or adapting without losing performance', '[{"en":"We need a scalable solution that grows with demand.","zh-TW":"我們需要一個能隨需求增長的可擴展解決方案。"},{"en":"The business model must be scalable to attract investors.","zh-TW":"商業模式必須具有可擴展性才能吸引投資者。"}]', 'business idiom'),
('disruptive innovation', '顛覆性創新', 'innovation that significantly alters an industry', '[{"en":"Disruptive innovation changed the entire retail landscape.","zh-TW":"顛覆性創新改變了整個零售業格局。"},{"en":"She led disruptive innovation at her previous company.","zh-TW":"她在上一家公司主導了顛覆性創新。"}]', 'business idiom'),
('stakeholder', '利益相關者；股東', 'any person who has an interest in a business or project', '[{"en":"All stakeholders must be informed of the decision.","zh-TW":"所有利益相關者必須被告知這個決定。"},{"en":"Stakeholder engagement is crucial for project success.","zh-TW":"利益相關者的參與對專案成功至關重要。"}]', 'business idiom'),
('buy-in', '認同；支持；首肯', 'agreement and support from key people', '[{"en":"We need buy-in from the board before proceeding.","zh-TW":"我們需要在繼續之前獲得董事會的認同。"},{"en":"Getting buy-in from all departments took two weeks.","zh-TW":"獲得所有部門的支持花了兩週時間。"}]', 'business idiom'),
('top line', '總收入；營收', 'total revenue before deductions', '[{"en":"The new product is expected to boost the top line.","zh-TW":"新產品預計將提升總收入。"},{"en":"We focus on top-line growth through new partnerships.","zh-TW":"我們通過新的合作關係專注於收入增長。"}]', 'business idiom'),
('agree on', '就…達成共識；同意', 'to reach an agreement about something', '[{"en":"We finally agreed on the contract terms.","zh-TW":"我們終於就合同條款達成了共識。"},{"en":"Can we agree on a delivery date by Friday?","zh-TW":"我們能在週五前就交貨日期達成共識嗎？"}]', 'phrasal verb'),
('build on', '以…為基礎；發展', 'to use as a foundation for further development', '[{"en":"Let us build on last year''s success.","zh-TW":"讓我們以去年的成功為基礎繼續發展。"},{"en":"She built on existing client relationships to expand business.","zh-TW":"她以現有客戶關係為基礎擴展了業務。"}]', 'phrasal verb'),
('close off', '關閉；截止', 'to end or prevent access to something', '[{"en":"By committing early you close off other options.","zh-TW":"早期承諾會關閉其他選項。"},{"en":"The deadline closes off submissions at midnight.","zh-TW":"截止日期在午夜關閉提交。"}]', 'phrasal verb'),
('fall through', '失敗；告吹', 'to fail to happen or to be cancelled', '[{"en":"The merger fell through at the last minute.","zh-TW":"合併在最後一刻告吹了。"},{"en":"The contract fell through after months of negotiation.","zh-TW":"合同在幾個月的談判後告吹了。"}]', 'phrasal verb'),
('gear up for', '為…做準備；積極備戰', 'to prepare for an important event or activity', '[{"en":"The team is gearing up for the product launch.","zh-TW":"團隊正在為產品發布做準備。"},{"en":"We are gearing up for the busiest quarter.","zh-TW":"我們正在為最繁忙的季度積極備戰。"}]', 'phrasal verb'),
('hang on to', '保留；緊抓；堅持', 'to keep or retain something', '[{"en":"We must hang on to our key clients.","zh-TW":"我們必須留住核心客戶。"},{"en":"It is hard to hang on to talent in this market.","zh-TW":"在這個市場留住人才很困難。"}]', 'phrasal verb'),
('invest in', '投資；投入資源', 'to spend money or effort on something for future benefit', '[{"en":"We invest heavily in employee development.","zh-TW":"我們大力投資員工發展。"},{"en":"She invested in new software to improve productivity.","zh-TW":"她投資了新軟體以提高生產力。"}]', 'phrasal verb'),
('knock back', '拒絕；擊退', 'to reject or refuse an offer or proposal', '[{"en":"The board knocked back the acquisition proposal.","zh-TW":"董事會拒絕了收購提案。"},{"en":"She was knocked back twice before landing the deal.","zh-TW":"她被拒絕兩次後才談成了交易。"}]', 'phrasal verb'),
('lead to', '導致；引起', 'to result in or cause something to happen', '[{"en":"This strategy could lead to significant cost savings.","zh-TW":"這個策略可能導致大幅成本節約。"},{"en":"Poor communication often leads to project failures.","zh-TW":"溝通不良往往導致專案失敗。"}]', 'phrasal verb'),
('lock in', '鎖定；確保', 'to secure or confirm an arrangement firmly', '[{"en":"We locked in the price before the rate increase.","zh-TW":"我們在漲價前鎖定了價格。"},{"en":"The long-term contract locks in the supply for two years.","zh-TW":"長期合同鎖定了兩年的供應。"}]', 'phrasal verb'),
('move ahead', '向前推進；繼續進行', 'to proceed or make progress', '[{"en":"We are ready to move ahead with the expansion.","zh-TW":"我們準備好推進擴張計劃了。"},{"en":"Please move ahead on the design phase.","zh-TW":"請繼續推進設計階段。"}]', 'phrasal verb'),
('object to', '反對；提出異議', 'to express disagreement or opposition', '[{"en":"Several members objected to the proposed changes.","zh-TW":"幾位成員反對提出的變更。"},{"en":"The union objected to the new working conditions.","zh-TW":"工會反對新的工作條件。"}]', 'phrasal verb'),
('patch up', '修補；和解', 'to repair a relationship or quickly fix a problem', '[{"en":"The two partners patched up their differences.","zh-TW":"兩位合夥人修補了他們的分歧。"},{"en":"They patched up the agreement with a compromise.","zh-TW":"他們通過妥協修補了協議。"}]', 'phrasal verb'),
('plan ahead', '提前規劃；預先計劃', 'to prepare in advance for future needs', '[{"en":"Always plan ahead to avoid last-minute problems.","zh-TW":"一定要提前規劃以避免最後一刻的問題。"},{"en":"She planned ahead for the transition period.","zh-TW":"她提前規劃了過渡期。"}]', 'phrasal verb'),
('reach out to', '聯繫；接觸', 'to make contact with someone for help or information', '[{"en":"Please reach out to the client for clarification.","zh-TW":"請聯繫客戶以獲得澄清。"},{"en":"She reached out to industry experts for advice.","zh-TW":"她聯繫了業界專家尋求建議。"}]', 'phrasal verb'),
('report back', '回報；匯報', 'to provide information or findings after investigation', '[{"en":"Please report back after your meeting with the client.","zh-TW":"請在與客戶開會後回報。"},{"en":"She reported back with a full analysis of the market.","zh-TW":"她回報了完整的市場分析。"}]', 'phrasal verb'),
('respond to', '回應；對…做出反應', 'to reply to or react to something', '[{"en":"Please respond to the client email by end of day.","zh-TW":"請在今天下班前回覆客戶的電子郵件。"},{"en":"The company responded to market changes quickly.","zh-TW":"公司迅速回應了市場變化。"}]', 'phrasal verb'),
('shake up', '大力改革；震動', 'to make major changes to an organization or system', '[{"en":"The new CEO shook up the management structure.","zh-TW":"新執行長大力改革了管理架構。"},{"en":"The startup is shaking up the traditional banking industry.","zh-TW":"這家新創公司正在顛覆傳統銀行業。"}]', 'phrasal verb'),
('slow down', '放慢速度；減緩', 'to reduce speed, pace, or intensity', '[{"en":"Supply chain issues slowed down our production.","zh-TW":"供應鏈問題減緩了我們的生產速度。"},{"en":"Growth has slowed down in the domestic market.","zh-TW":"國內市場的增長已經減緩。"}]', 'phrasal verb'),
('stand up to', '經得起；抵抗', 'to withstand scrutiny or challenges', '[{"en":"Does this proposal stand up to careful analysis?","zh-TW":"這個提案能經得起仔細分析嗎？"},{"en":"The product must stand up to harsh market conditions.","zh-TW":"產品必須能夠抵抗嚴苛的市場狀況。"}]', 'phrasal verb'),
('step up', '加強；提升；挺身而出', 'to increase effort, or to take greater responsibility', '[{"en":"The team stepped up during the critical phase.","zh-TW":"在關鍵階段團隊挺身而出。"},{"en":"We need to step up our marketing efforts.","zh-TW":"我們需要加強行銷工作。"}]', 'phrasal verb'),
('stick with', '堅持；繼續使用', 'to continue with something rather than changing', '[{"en":"We decided to stick with the current supplier.","zh-TW":"我們決定繼續使用現有的供應商。"},{"en":"She stuck with her original proposal and won.","zh-TW":"她堅持了原來的提案並成功了。"}]', 'phrasal verb'),
('sum up', '總結；概括', 'to briefly summarize the main points', '[{"en":"Can you sum up the key takeaways?","zh-TW":"你能總結主要收穫嗎？"},{"en":"She summed up the discussion in two clear points.","zh-TW":"她用兩個清晰的要點總結了討論。"}]', 'phrasal verb'),
('team up', '合作；組隊', 'to join forces with someone for a common purpose', '[{"en":"We teamed up with a local firm to enter the market.","zh-TW":"我們與一家本地公司合作進入市場。"},{"en":"The two departments teamed up on the project.","zh-TW":"兩個部門聯合推進了這個專案。"}]', 'phrasal verb'),
('think through', '仔細考慮；深思熟慮', 'to consider something carefully and thoroughly', '[{"en":"Please think through the implications before deciding.","zh-TW":"做決定前請仔細考慮其影響。"},{"en":"She thought through every scenario before presenting.","zh-TW":"她在發表前深思熟慮了每個情境。"}]', 'phrasal verb'),
('touch on', '提及；簡略談及', 'to mention briefly in passing', '[{"en":"She touched on the budget issue in her presentation.","zh-TW":"她在簡報中提及了預算問題。"},{"en":"The report touches on several key challenges.","zh-TW":"報告簡略提及了幾個關鍵挑戰。"}]', 'phrasal verb'),
('trade off', '以…換取；權衡取捨', 'to accept a disadvantage in exchange for a benefit', '[{"en":"We traded off speed for accuracy in the process.","zh-TW":"我們在流程中以犧牲速度換取準確性。"},{"en":"There are always trade-offs between cost and quality.","zh-TW":"成本與品質之間總是存在取捨。"}]', 'phrasal verb'),
('wind up', '結束；清算；最終到達', 'to end up in a situation, or to close down', '[{"en":"The failed startup wound up with huge debts.","zh-TW":"失敗的新創公司最終背負了巨額債務。"},{"en":"They wound up the subsidiary after three unprofitable years.","zh-TW":"三年虧損後他們清算了子公司。"}]', 'phrasal verb'),
('the ball is in your court', '現在輪到你了；決定權在你', 'it is now the other person''s turn to act or decide', '[{"en":"We submitted the offer — the ball is in their court.","zh-TW":"我們提交了報價——現在決定權在他們那邊。"},{"en":"I have made my position clear; the ball is in your court.","zh-TW":"我已表明立場；現在輪到你了。"}]', 'expression'),
('behind the scenes', '幕後；在檯面下', 'in private, without public visibility', '[{"en":"A lot of hard work happens behind the scenes.","zh-TW":"許多艱辛的工作都在幕後進行。"},{"en":"She worked behind the scenes to secure the partnership.","zh-TW":"她在幕後努力確保了合作關係的建立。"}]', 'expression'),
('break new ground', '開拓新領域；創新', 'to do something innovative or pioneering', '[{"en":"This product breaks new ground in renewable energy.","zh-TW":"這款產品在可再生能源領域開拓了新領域。"},{"en":"She broke new ground with her research on AI ethics.","zh-TW":"她在人工智慧倫理研究方面開拓了新領域。"}]', 'expression'),
('bring home the bacon', '養家；賺錢維持生計', 'to earn money to support oneself or family', '[{"en":"With two kids she is determined to bring home the bacon.","zh-TW":"有兩個孩子她下定決心要養家。"},{"en":"The new contract will really bring home the bacon.","zh-TW":"新合同真的能帶來可觀的收入。"}]', 'expression'),
('burn bridges', '斷絕關係；自絕退路', 'to permanently damage a relationship or future opportunities', '[{"en":"Do not burn bridges when leaving a company.","zh-TW":"離職時不要斷絕關係自絕退路。"},{"en":"She burned bridges with the client over a pricing dispute.","zh-TW":"她因定價糾紛與客戶斷絕了關係。"}]', 'expression'),
('change gears', '轉換策略；改變節奏', 'to change approach, pace, or direction', '[{"en":"After poor results we changed gears and tried a new approach.","zh-TW":"在成績不佳後我們轉換策略嘗試了新方法。"},{"en":"It is time to change gears and focus on retention.","zh-TW":"是時候改變節奏專注於客戶留存了。"}]', 'expression'),
('cover all bases', '面面俱到；覆蓋所有情況', 'to deal with every possible situation or eventuality', '[{"en":"The risk assessment covered all bases.","zh-TW":"風險評估面面俱到。"},{"en":"She made sure to cover all bases before the negotiation.","zh-TW":"她在談判前確保面面俱到。"}]', 'expression'),
('dig deep', '深入挖掘；付出極大努力', 'to make a great effort or examine something thoroughly', '[{"en":"We dug deep to understand the customer''s real needs.","zh-TW":"我們深入挖掘以了解客戶的真實需求。"},{"en":"When the market shifted she dug deep to find a solution.","zh-TW":"市場轉變時她付出了極大努力尋找解決方案。"}]', 'expression'),
('do the math', '算一算；考慮清楚', 'to think about the numbers or logic of a situation', '[{"en":"Do the math — at this rate we will not break even.","zh-TW":"算一算——以這個速度我們無法收支平衡。"},{"en":"She did the math and decided to outsource.","zh-TW":"她計算了一下決定外包。"}]', 'expression'),
('draw the line', '劃定界限；設定底線', 'to set a firm limit on what is acceptable', '[{"en":"We draw the line at requests that compromise quality.","zh-TW":"我們對損害品質的要求劃定了界限。"},{"en":"Management drew the line at offering further discounts.","zh-TW":"管理層對進一步折扣設定了底線。"}]', 'expression'),
('explore all avenues', '探索所有可能；窮盡選項', 'to investigate every possible option or solution', '[{"en":"We explored all avenues before accepting the loss.","zh-TW":"我們在接受損失之前探索了所有可能。"},{"en":"The team explored all avenues for cost reduction.","zh-TW":"團隊探索了所有降低成本的途徑。"}]', 'expression'),
('get to the bottom of', '查明真相；徹底調查', 'to find out the real cause of something', '[{"en":"We need to get to the bottom of this quality issue.","zh-TW":"我們需要查明這個品質問題的真相。"},{"en":"She got to the bottom of the data discrepancy.","zh-TW":"她徹底調查了數據差異的原因。"}]', 'expression');